		public void OpenResult() {
			int num = BattleMatchingWork.GetPlayerNum();
			int mine = BattleMatchingWork.GetIndexMine();
			switch (BattleMatchingWork.battleResult)
			{
				case Dpr.Battle.Logic.BtlResult.BTL_RESULT_LOSE:
					if (mine < num / 2)
					{
						_imageResultA.sprite = _spriteResultLose;
						_imageResultB.sprite = _spriteResultWin;
					}
					else
					{
						_imageResultA.sprite = _spriteResultWin;
						_imageResultB.sprite = _spriteResultLose;
					}
					break;
				case Dpr.Battle.Logic.BtlResult.BTL_RESULT_WIN:
					if (mine < num / 2)
					{
						_imageResultA.sprite = _spriteResultWin;
						_imageResultB.sprite = _spriteResultLose;
					}
					else
					{
						_imageResultA.sprite = _spriteResultLose;
						_imageResultB.sprite = _spriteResultWin;
					}
					break;
			}
			bool isDraw = BattleMatchingWork.battleResult == Dpr.Battle.Logic.BtlResult.BTL_RESULT_DRAW;
			_imageResultA.SetActive(!isDraw);
			_imageResultB.SetActive(!isDraw);
			_imageResultDraw.SetActive(isDraw);
			_objResult.SetActive(true);
		}
